	protected BIQuery read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created BIQuery" );

		BIQuery entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read BIQuery with primary key" );
		msg.append( bIQueryId );
		
		BIQueryFetchOneSummary fetchOneSummary = new BIQueryFetchOneSummary( bIQueryId );

		try {
			entity = BIQueryService.getBIQueryInstance().getBIQuery( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found BIQuery " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a BIQuery.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a BIQuery." );

		StringBuilder msg = new StringBuilder( "Failed to update a BIQuery : " );        
		BIQuery entity = read();
		UpdateBIQueryCommand command = generateUpdateCommand();
		command.setBIQueryId(entity.getBIQueryId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created BIQuery." );

			// for use later on...
			bIQueryId = entity.getBIQueryId();

			BIQueryService proxy = BIQueryService.getBIQueryInstance();  

			proxy.updateBIQuery( command ).get();

			LOGGER.info( "-- Successfully saved BIQuery - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + bIQueryId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a BIQuery.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created BIQuery." );

		BIQuery entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read BIQuery with id " + bIQueryId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read BIQuery with id " + bIQueryId );

			throw e;
		}

		try{
			BIQueryService.getBIQueryInstance().delete( new DeleteBIQueryCommand( entity.getBIQueryId() ) ).get();
			LOGGER.info( "-- Successfully deleted BIQuery with id " + bIQueryId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete BIQuery with id " + bIQueryId );

			throw e;
		}
	}

	/**
	 * get all BIQuerys.
	 */
	protected List<BIQuery> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of BIQuerys:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all BIQuery : " );        
		List<BIQuery> collection  = new ArrayList<>();

		try {
			// call the static get method on the BIQueryService
			collection = BIQueryService.getBIQueryInstance().getAllBIQuery();
			assertNotNull( collection, "An Empty collection of BIQuery was incorrectly returned.");
			
			// Now print out the values
			BIQuery entity = null;            
			Iterator<BIQuery> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getBIQueryId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

